mod audio;mod game;mod video;
use game::Game;
fn main(){let mut out=vec![];for (typ,handler) in [(2,0x84e6),(3,0x84e6),(44,0xa5f5),(45,0xa534),(46,0xb40b)]{let mut g=Game::new(false).unwrap();g.memory.fill(0);g.memory[0x530]=1;g.memory[0x5b0]=80;g.memory[0x570]=160;g.memory[0x720]=typ;g.memory[0x710]=80;g.memory[0x560]=80;let mut samples=vec![];for tick in 0..600 {g.actor_call(handler,0).unwrap();let mut shots=vec![];for j in 1..16{if g.memory[0x720+j]!=0 {shots.push(g.memory[0x720+j]);g.memory[0x720+j]=0;}}samples.push(serde_json::json!({"tick":tick,"sprite":g.memory[0x500],"palette":g.memory[0x540],"direction":g.memory[0x6c0],"target_x":g.memory[0x5b0],"target_y":g.memory[0x570],"flips":g.memory[0x6a],"x":g.memory[0x710],"y":g.memory[0x560],"state":g.memory[0x520],"timer":g.memory[0x670],"shots":shots}));}out.push(serde_json::json!({"source_type":typ,"samples":samples}));}println!("{}",serde_json::to_string_pretty(&out).unwrap());}
